package com.example.order.product;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.Instant;

@Entity
@Table(name = "products")
public class Product {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 100)
    private String name;

    @Column(nullable = false)
    private long price;

    @Column(nullable = false)
    private int stock;

    @Column(nullable = false)
    private int reserved;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    protected Product() {
    }

    public Product(String name, long price, int stock, Instant createdAt) {
        this.name = name;
        this.price = price;
        this.stock = stock;
        this.reserved = 0;
        this.createdAt = createdAt;
    }

    public int available() {
        return stock - reserved;
    }

    /** 결제 대기 주문을 위해 수량을 잡아 둔다. */
    public void reserve(int quantity) {
        if (quantity > available()) {
            throw new IllegalStateException("insufficient stock for product " + id);
        }
        reserved += quantity;
    }

    /** 결제 대기 주문이 끝나지 못해 잡아 둔 수량을 돌려놓는다. */
    public void release(int quantity) {
        reserved -= quantity;
    }

    /** 결제 승인: 잡아 둔 수량이 판매된다. */
    public void sellReserved(int quantity) {
        reserved -= quantity;
        stock -= quantity;
    }

    /** 환불: 판매된 수량이 재고로 돌아온다. */
    public void restock(int quantity) {
        stock += quantity;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public long getPrice() {
        return price;
    }

    public int getStock() {
        return stock;
    }

    public int getReserved() {
        return reserved;
    }
}
EOF
